function nivel(n) {
  if (n > 100) {
    return "alto";
  }
  return "bajo";
}
const casos = [50, 100, 101];
for (const n of casos) {
  test(`${n}`, () => {
    expect(nivel(n)).toBe("bajo");
  });
}

